/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface ChatSearchMessage {
  id: string
  role: "user" | "assistant"
  text: string
}

export interface ChatSearchChat {
  id: string
  title: string
  updatedAt: Date | number | string
  messages: ChatSearchMessage[]
}

/** `all`, only what the user wrote, or only the assistant's replies. */
export type ChatSearchRole = "all" | "user" | "assistant"

/* -------------------------------------------------------------------------------------------------
 * Matching
 *
 * Two matchers share one result shape, a score and the ranges to emphasize:
 * - `fuzzyMatch` for short labels (command palette, thread titles): the query letters in order,
 *   rewarded for word starts and runs, so "nwc" finds "New chat" and "rspg" finds "Runs page".
 * - `findTerms` for full text (chat search): every word of the query as a substring, so the
 *   snippet shows exactly what matched.
 * -----------------------------------------------------------------------------------------------*/

/** Half-open `[start, end)` character ranges into the searched text. */
type MatchRange = readonly [start: number, end: number]

/* -------------------------------------------------------------------------------------------------
 * Snippets
 * -----------------------------------------------------------------------------------------------*/

interface Snippet {
  text: string
  ranges: MatchRange[]
  /** Text was cut before or after the window. */
  before: boolean
  after: boolean
}

export interface ChatSearchResult {
  /** Unique row key. */
  id: string
  chatId: string
  title: string
  /** Ranges of `title` that matched. */
  titleRanges?: MatchRange[]
  /** The message the snippet comes from, to scroll to it on open. */
  messageId?: string
  role?: "user" | "assistant"
  /** A plain string, or a window with match ranges from `snippetAround`. */
  snippet?: Snippet | string
  /** Matches across the whole chat. Shown when more than one. */
  matchCount?: number
  updatedAt: Date | number | string
}

interface FuzzyResult {
  /** Higher is better. Comparable between items for the same query only. */
  score: number
  ranges: MatchRange[]
}

/** Lowercase and strip accents so "resume" finds "Résumé", only when lengths (and ranges) hold. */
function fold(text: string) {
  const lower = text.toLowerCase()
  const stripped = lower.normalize("NFD").replace(/\p{M}/gu, "")
  return stripped.length === lower.length ? stripped : lower
}

const WORD_BREAK = /[\s\-_/.:,()[\]]/

function mergeRanges(ranges: MatchRange[]): MatchRange[] {
  const sorted = [...ranges].sort((a, b) => a[0] - b[0])
  const out: [number, number][] = []
  for (const [s, e] of sorted) {
    const last = out[out.length - 1]
    if (last && s <= last[1]) last[1] = Math.max(last[1], e)
    else out.push([s, e])
  }
  return out
}

/**
 * Every whitespace-separated term of the query as a case-insensitive substring of the text.
 * Returns null unless all terms are present. Used for full-text search across messages.
 */
function findTerms(query: string, text: string): FuzzyResult | null {
  const terms = fold(query).split(/\s+/).filter(Boolean)
  if (!terms.length) return null
  const t = fold(text)
  const ranges: MatchRange[] = []
  let score = 0
  for (const term of terms) {
    let hits = 0
    for (let i = t.indexOf(term); i !== -1; i = t.indexOf(term, i + term.length)) {
      ranges.push([i, i + term.length])
      hits++
      if (i === 0 || WORD_BREAK.test(t[i - 1] ?? "")) score += 2
    }
    if (!hits) return null
    score += Math.min(hits, 5)
  }
  return { score, ranges: mergeRanges(ranges) }
}

/* -------------------------------------------------------------------------------------------------
 * Search
 * -----------------------------------------------------------------------------------------------*/

function toTime(value: ChatSearchChat["updatedAt"]) {
  return value instanceof Date ? value.getTime() : new Date(value).getTime()
}

/**
 * A window of `radius` characters around the first match, snapped to word boundaries, with the
 * ranges shifted into it. Whitespace runs collapse so a snippet is one clean line.
 */
function snippetAround(text: string, ranges: MatchRange[], radius = 64): Snippet {
  const flat = text.replace(/\s+/g, " ")
  // Collapsing whitespace shifts offsets; recompute ranges against the flat text.
  const map: number[] = []
  let j = 0
  for (let i = 0; i < text.length; i++) {
    const ws = /\s/.test(text[i] ?? "")
    if (ws && i > 0 && /\s/.test(text[i - 1] ?? "")) {
      map.push(j - 1)
      continue
    }
    map.push(j)
    j++
  }
  const shifted = ranges.map(([s, e]) => [map[s] ?? 0, (map[e - 1] ?? 0) + 1] as const)
  const first = shifted[0]
  if (!first) {
    const cut = flat.length > radius * 2
    return {
      text: cut ? flat.slice(0, radius * 2).trimEnd() : flat,
      ranges: [],
      before: false,
      after: cut,
    }
  }
  let start = Math.max(0, first[0] - Math.round(radius * 0.6))
  let end = Math.min(flat.length, first[1] + radius + Math.round(radius * 0.4))
  if (start > 0) {
    const space = flat.indexOf(" ", start)
    if (space !== -1 && space < first[0]) start = space + 1
  }
  if (end < flat.length) {
    const space = flat.lastIndexOf(" ", end)
    if (space > first[1]) end = space
  }
  return {
    text: flat.slice(start, end),
    ranges: shifted
      .filter(([s, e]) => e > start && s < end)
      .map(([s, e]) => [Math.max(0, s - start), Math.min(end, e) - start] as const),
    before: start > 0,
    after: end < flat.length,
  }
}

/**
 * Full-text search across chats. Every word of the query must appear in one message (or the
 * title). One result per chat, with the best message as a word-snapped snippet, ranked by title
 * hits, then match quality, then recency.
 */
export function searchChats(
  chats: readonly ChatSearchChat[],
  query: string,
  { role = "all", limit = 50 }: { role?: ChatSearchRole; limit?: number } = {},
): ChatSearchResult[] {
  if (!query.trim()) return []
  const scored: { result: ChatSearchResult; score: number; time: number }[] = []
  for (const chat of chats) {
    const titleHit = role === "all" ? findTerms(query, chat.title) : null
    let best: { message: ChatSearchMessage; score: number; ranges: MatchRange[] } | null = null
    let count = 0
    for (const message of chat.messages) {
      if (role !== "all" && message.role !== role) continue
      const hit = findTerms(query, message.text)
      if (!hit) continue
      count += hit.ranges.length
      if (!best || hit.score > best.score) best = { message, score: hit.score, ranges: hit.ranges }
    }
    if (!best && !titleHit) continue
    const source = best?.message ?? chat.messages.find((m) => m.role === "user") ?? chat.messages[0]
    scored.push({
      score:
        (titleHit ? titleHit.score * 3 + 10 : 0) + (best?.score ?? 0) + Math.min(count, 10) * 0.5,
      time: toTime(chat.updatedAt),
      result: {
        id: `${chat.id}:${source?.id ?? "title"}`,
        chatId: chat.id,
        title: chat.title,
        titleRanges: titleHit?.ranges,
        messageId: source?.id,
        role: source?.role,
        snippet: source ? snippetAround(source.text, best?.ranges ?? [], 110) : undefined,
        matchCount: count + (titleHit?.ranges.length ?? 0),
        updatedAt: chat.updatedAt,
      },
    })
  }
  return scored
    .sort((a, b) => b.score - a.score || b.time - a.time)
    .slice(0, limit)
    .map((s) => s.result)
}

/* -------------------------------------------------------------------------------------------------
 * Dates
 * -----------------------------------------------------------------------------------------------*/

const DAY = 86_400_000

/** "Today", "Yesterday", a weekday within a week, then "Sep 14", or "Sep 14, 2025" in other years. */
export function formatChatDate(value: ChatSearchChat["updatedAt"], now: number, locale?: string) {
  const time = toTime(value)
  const start = new Date(now)
  start.setHours(0, 0, 0, 0)
  const today = start.getTime()
  if (time >= today) return "Today"
  if (time >= today - DAY) return "Yesterday"
  const date = new Date(time)
  if (time >= today - 6 * DAY)
    return new Intl.DateTimeFormat(locale, { weekday: "long" }).format(date)
  const sameYear = date.getFullYear() === start.getFullYear()
  return new Intl.DateTimeFormat(locale, {
    month: "short",
    day: "numeric",
    year: sameYear ? undefined : "numeric",
  }).format(date)
}

/* -------------------------------------------------------------------------------------------------
 * ChatSearch
 * -----------------------------------------------------------------------------------------------*/

export interface ChatSearchProps
  extends Omit<React.ComponentProps<"div">, "onError" | "role" | "results"> {
  /** Chats to search locally. Leave out and pass `results` to search on a server. */
  chats?: ChatSearchChat[]
  /** Server results for the current query. Turns local search off. */
  results?: ChatSearchResult[]
  query?: string
  defaultQuery?: string
  /** Debounced by `debounceMs` in server mode. */
  onQueryChange?: (query: string) => void
  /** Server mode: a request is in flight. Results stay on screen; a spinner shows after 200 ms. */
  loading?: boolean
  /** Shows the error state with Retry. A string replaces the default message. */
  error?: boolean | string | null
  onRetry?: () => void
  /** Enter opens, Cmd/Ctrl+Enter or a middle click opens in a new tab. */
  onOpen?: (result: ChatSearchResult, options: { newTab: boolean }) => void
  /** Who the replies come from, in the snippet and the filter. Default "Assistant". */
  assistantName?: string
  /** Show All, Your messages and replies filters. Default true. */
  roleFilter?: boolean
  role?: ChatSearchRole
  defaultRole?: ChatSearchRole
  onRoleChange?: (role: ChatSearchRole) => void
  /** Recent chats while the query is empty. Default 6; 0 shows nothing. */
  recentLimit?: number
  /** Reference time for dates. Pass a fixed date for stable demos and tests. */
  now?: Date | number
  locale?: string
  /** Delay before `onQueryChange` fires in server mode, and before local results update. */
  debounceMs?: number
  placeholder?: string
  /** Escape clears the query first. Default true; the dialog turns it off so Escape closes. */
  clearOnEscape?: boolean
  autoFocus?: boolean
  inputRef?: React.Ref<HTMLInputElement>
  /** Force Mac or PC labels in the hint row. */
  apple?: boolean
}

type DialogSize = "sm" | "md" | "lg" | "xl" | "full"

interface DialogContentProps extends React.ComponentProps<typeof DialogPrimitive.Popup> {
  size?: DialogSize
  /** Render the close button in the corner. On by default. */
  showClose?: boolean
  /** Classes for the scrim behind the popup. */
  backdropClassName?: string
  container?: React.ComponentProps<typeof DialogPrimitive.Portal>["container"]
}

/* -------------------------------------------------------------------------------------------------
 * Motion
 *
 * Scrim and popup share one duration and curve: 220 ms in, 160 ms out, ease-chatcn-out. The popup
 * grows from 0.96 at the center and leaves at 0.98 (exits travel less). Opened or closed from the
 * keyboard, nothing animates: Enter and Esc should feel instant.
 * -----------------------------------------------------------------------------------------------*/

const InstantContext = React.createContext(false)

const sizes: Record<DialogSize, string> = {
  sm: "w-[min(24rem,calc(100vw-2rem))]",
  md: "w-[min(32rem,calc(100vw-2rem))]",
  lg: "w-[min(44rem,calc(100vw-2rem))]",
  xl: "w-[min(64rem,calc(100vw-2rem))]",
  full: "h-[calc(100dvh-2rem)] w-[calc(100vw-2rem)]",
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes2: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes2[size])
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"m6 6 12 12"}],
  ["path", {"d":"m18 6-3.88 3.88"}],
  ["path", {"d":"M9.88 14.12 6 18"}],
]

const XIcon: Icon = /* @__PURE__ */ createIcon("x", iconNode)

function DialogContent({
  size = "md",
  showClose = true,
  backdropClassName,
  container,
  className,
  children,
  ...props
}: DialogContentProps) {
  const instant = React.useContext(InstantContext)
  return (
    <DialogPrimitive.Portal container={container}>
      <DialogPrimitive.Backdrop
        data-slot="dialog-backdrop"
        data-dialog-instant={instant ? "" : undefined}
        className={cn(
          "bg-(color:--chatcn-scrim) fixed inset-0 z-50",
          "ease-(--chatcn-ease-out) transition-opacity duration-220",
          "data-[ending-style]:opacity-0 data-[ending-style]:duration-160 data-[starting-style]:opacity-0",
          "data-[dialog-instant]:transition-none",
          backdropClassName,
        )}
      />
      <DialogPrimitive.Popup
        data-slot="dialog-content"
        data-size={size}
        data-dialog-instant={instant ? "" : undefined}
        className={cn(
          "bg-(color:--chatcn-surface) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xl) rounded-(--chatcn-radius-xl) fixed top-1/2 left-1/2 z-50 -translate-x-1/2 -translate-y-1/2",
          "flex max-h-[calc(100dvh-2rem)] origin-center flex-col overflow-hidden outline-none",
          sizes[size],
          "ease-(--chatcn-ease-out) transition-[opacity,scale] duration-220",
          "data-[starting-style]:scale-(--chatcn-enter-scale) data-[starting-style]:opacity-0",
          "data-[ending-style]:scale-(--chatcn-exit-scale) data-[ending-style]:opacity-0 data-[ending-style]:duration-160",
          "motion-reduce:data-[ending-style]:scale-100",
          "data-[dialog-instant]:transition-none",
          // Forced colors strip shadows, so the hairline needs a real outline.
          "forced-colors:outline-1 forced-colors:outline-solid",
          className,
        )}
        {...props}
      >
        {children}
        {showClose ? (
          <DialogPrimitive.Close
            aria-label="Close"
            data-slot="dialog-close"
            className={cn(
              buttonVariants({ variant: "ghost", size: "icon-sm" }),
              "absolute end-3 top-3 pointer-coarse:size-11",
            )}
          >
            <XIcon />
          </DialogPrimitive.Close>
        ) : null}
      </DialogPrimitive.Popup>
    </DialogPrimitive.Portal>
  )
}

/* -------------------------------------------------------------------------------------------------
 * ChatSearchDialog
 * -----------------------------------------------------------------------------------------------*/

export interface ChatSearchDialogProps extends Omit<ChatSearchProps, "clearOnEscape" | "autoFocus"> {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Opens the dialog from anywhere, for example `mod+shift+f`. Off by default. */
  hotkey?: string | null
  /** Accessible name. Default "Search chats". */
  title?: string
  container?: React.ComponentProps<typeof DialogContent>["container"]
}

/* -------------------------------------------------------------------------------------------------
 * Hotkey strings
 *
 * A hotkey is a `+` separated combo, case insensitive: `mod+k`, `mod+shift+o`, `mod+/`, `shift+?`,
 * `escape`, `/`. `mod` is Cmd on Apple platforms and Ctrl everywhere else, so one binding works on
 * every keyboard. Several combos can share a handler: `"mod+k, mod+p"`.
 * -----------------------------------------------------------------------------------------------*/

type HotkeyHandler = (event: KeyboardEvent) => void

interface HotkeyOptions {
  /** Skip the binding without unbinding it. */
  enabled?: boolean
  /**
   * Fire while focus is in a text field. Defaults to true for combos with Cmd, Ctrl or Alt and
   * false for bare keys, so typing `/` in the composer never steals focus.
   */
  allowInInput?: boolean
  /** Call `preventDefault` when the combo fires. Default true. */
  preventDefault?: boolean
}

type HotkeyMap = Record<string, HotkeyHandler | ({ handler: HotkeyHandler } & HotkeyOptions)>

/* -------------------------------------------------------------------------------------------------
 * useChatcnHotkeys
 * -----------------------------------------------------------------------------------------------*/

interface UseChatcnHotkeysOptions {
  /** Turn every binding off at once, for example while a dialog owns the keyboard. */
  enabled?: boolean
  /** Listen on this element instead of the window. */
  target?: React.RefObject<HTMLElement | null>
}

interface ParsedHotkey {
  key: string
  mod: boolean
  meta: boolean
  ctrl: boolean
  shift: boolean
  alt: boolean
}

const KEY_ALIASES: Record<string, string> = {
  esc: "escape",
  return: "enter",
  space: " ",
  up: "arrowup",
  down: "arrowdown",
  left: "arrowleft",
  right: "arrowright",
  del: "delete",
  plus: "+",
  // "," separates alternative combos, so the comma key is spelled out: `mod+comma`.
  comma: ",",
}

function parseHotkey(combo: string): ParsedHotkey {
  // A trailing "+" is the plus key itself, so `mod++` is Cmd and plus.
  const parts = combo.trim().toLowerCase().replace(/\+\+$/, "+plus").split("+")
  const parsed: ParsedHotkey = {
    key: "",
    mod: false,
    meta: false,
    ctrl: false,
    shift: false,
    alt: false,
  }
  for (const raw of parts) {
    const part = raw.trim()
    if (part === "mod") parsed.mod = true
    else if (part === "meta" || part === "cmd" || part === "command") parsed.meta = true
    else if (part === "ctrl" || part === "control") parsed.ctrl = true
    else if (part === "shift") parsed.shift = true
    else if (part === "alt" || part === "option") parsed.alt = true
    else parsed.key = KEY_ALIASES[part] ?? part
  }
  return parsed
}

/** True on macOS, iOS and iPadOS, where `mod` means Cmd. */
function isApplePlatform() {
  if (typeof navigator === "undefined") return false
  const platform =
    (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData?.platform ??
    navigator.platform ??
    ""
  return /mac|iphone|ipad|ipod/i.test(platform)
}

/** Shifted symbols arrive as their own key on US layouts (`?` for Shift+/), so accept both. */
const SHIFTED: Record<string, string> = { "?": "/", "<": ",", ">": ".", ":": ";", "{": "[" }

function matchesHotkey(event: KeyboardEvent, hotkey: ParsedHotkey, apple = isApplePlatform()) {
  const wantMeta = hotkey.meta || (hotkey.mod && apple)
  const wantCtrl = hotkey.ctrl || (hotkey.mod && !apple)
  if (event.metaKey !== wantMeta || event.ctrlKey !== wantCtrl || event.altKey !== hotkey.alt)
    return false
  const key = event.key?.toLowerCase() ?? ""
  // Shift is implied by symbols like `?`, so only check it for letters, digits and named keys.
  const symbol = key.length === 1 && !/[a-z0-9]/.test(key)
  if (!symbol && event.shiftKey !== hotkey.shift) return false
  if (key === hotkey.key) return true
  if (SHIFTED[key] === hotkey.key && hotkey.shift) return true
  // Alt and Option remap letters on macOS (Option+K is "˚"), so fall back to the physical key.
  const code = event.code?.toLowerCase() ?? ""
  return code === `key${hotkey.key}` || code === `digit${hotkey.key}`
}

function isEditable(target: EventTarget | null) {
  const el = target as HTMLElement | null
  if (!el || typeof el.closest !== "function") return false
  if (el.isContentEditable) return true
  const tag = el.tagName
  if (tag === "TEXTAREA" || tag === "SELECT") return true
  if (tag !== "INPUT") return false
  const type = (el as HTMLInputElement).type
  return !["button", "checkbox", "radio", "range", "submit", "reset", "color", "file"].includes(
    type,
  )
}

/**
 * Global keyboard shortcuts for app chrome. Handlers can change on every render without
 * re-binding. Never fires during IME composition, on auto-repeat for toggles, or for bare keys
 * while the user types in a field.
 *
 *   useChatcnHotkeys({
 *     "mod+k": () => setPaletteOpen((o) => !o),
 *     "mod+shift+o": newChat,
 *     "mod+/": () => setShortcutsOpen(true),
 *   })
 */
function useChatcnHotkeys(
  map: HotkeyMap,
  { enabled = true, target }: UseChatcnHotkeysOptions = {},
) {
  const mapRef = React.useRef(map)
  mapRef.current = map
  const signature = Object.keys(map).join("|")

  React.useEffect(() => {
    if (!enabled) return
    const bindings = signature
      .split("|")
      .filter(Boolean)
      .map((combo) => ({ combo, parsed: combo.split(",").map(parseHotkey) }))
    const apple = isApplePlatform()
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.isComposing || event.keyCode === 229 || event.defaultPrevented) return
      for (const { combo, parsed } of bindings) {
        const entry = mapRef.current[combo]
        if (!entry) continue
        const { handler, ...options } = typeof entry === "function" ? { handler: entry } : entry
        if (options.enabled === false) continue
        const hit = parsed.find((p) => matchesHotkey(event, p, apple))
        if (!hit) continue
        const modified = hit.mod || hit.meta || hit.ctrl || hit.alt
        const allowInInput = options.allowInInput ?? modified
        if (!allowInInput && isEditable(event.target)) continue
        if (event.repeat && modified) {
          event.preventDefault()
          return
        }
        if (options.preventDefault !== false) event.preventDefault()
        handler(event)
        return
      }
    }
    const node: HTMLElement | Window = target?.current ?? window
    node.addEventListener("keydown", onKeyDown as EventListener)
    return () => node.removeEventListener("keydown", onKeyDown as EventListener)
  }, [enabled, signature, target])
}

let lastModality: "keyboard" | "pointer" = "keyboard"

let tracking = false

function trackModality() {
  if (tracking || typeof document === "undefined") return
  tracking = true
  document.addEventListener("keydown", () => (lastModality = "keyboard"), true)
  document.addEventListener("pointerdown", () => (lastModality = "pointer"), true)
}

type DialogProps = React.ComponentProps<typeof DialogPrimitive.Root>

/** A keyboard Enter on a button arrives as a click with `detail === 0`. */
function isKeyboardEvent(event: Event | undefined) {
  if (!event) return false
  if (typeof KeyboardEvent !== "undefined" && event instanceof KeyboardEvent) return true
  return event.type === "click" && (event as MouseEvent).detail === 0
}

function Dialog({ onOpenChange, ...props }: DialogProps) {
  const [instant, setInstant] = React.useState(false)
  return (
    <InstantContext.Provider value={instant}>
      <DialogPrimitive.Root
        onOpenChange={(open, details) => {
          setInstant(isKeyboardEvent(details.event))
          onOpenChange?.(open, details)
        }}
        {...props}
      />
    </InstantContext.Provider>
  )
}

function DialogTitle({ className, ...props }: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn("text-[1rem]/[1.5rem] tracking-[-0.01em] text-(color:--chatcn-fg) pe-8 font-semibold text-balance", className)}
      {...props}
    />
