}

function noopSubscribe() {
  return () => {}
}

/** Client-side platform check that renders the same on the server and the first client pass. */
function useApplePlatform() {
  return React.useSyncExternalStore(noopSubscribe, isApplePlatform, () => true)
}

/** Debounces a fast-changing value, for queries that hit a server. */
function useChatcnShellDebounced<T>(value: T, delayMs = 150) {
  const [debounced, setDebounced] = React.useState(value)
  React.useEffect(() => {
    if (delayMs <= 0) {
      setDebounced(value)
      return
    }
    const id = window.setTimeout(() => setDebounced(value), delayMs)
    return () => window.clearTimeout(id)
  }, [value, delayMs])
  return debounced
}

/** The latest chats as results, for the idle state. The snippet is the latest message. */
function recentChats(chats: readonly ChatSearchChat[], limit: number): ChatSearchResult[] {
  return [...chats]
    .sort((a, b) => toTime(b.updatedAt) - toTime(a.updatedAt))
    .slice(0, limit)
    .map((chat) => {
      const last = chat.messages[chat.messages.length - 1]
      return {
        id: `${chat.id}:recent`,
        chatId: chat.id,
        title: chat.title,
        messageId: last?.id,
        role: last?.role,
        // The whole message: the row clamps it to two lines.
        snippet: last ? snippetAround(last.text, [], 300) : undefined,
        updatedAt: chat.updatedAt,
      }
    })
}

function useDelayed(active: boolean, delay = 200) {
  const [shown, setShown] = React.useState(false)
  React.useEffect(() => {
    if (!active) {
      setShown(false)
      return
    }
    const id = window.setTimeout(() => setShown(true), delay)
    return () => window.clearTimeout(id)
  }, [active, delay])
  return shown
}

