}

const SYMBOLS_APPLE: Record<string, string> = {
  mod: "⌘",
  ctrl: "⌃",
  shift: "⇧",
  alt: "⌥",
}

const NAMES_OTHER: Record<string, string> = {
  meta: "Win",
  ctrl: "Ctrl",
  shift: "Shift",
  alt: "Alt",
}

const KEY_LABELS: Record<string, string> = {
  enter: "↵",
  escape: "Esc",
  arrowup: "↑",
  arrowdown: "↓",
  arrowleft: "←",
  arrowright: "→",
  backspace: "⌫",
  delete: "Del",
  tab: "Tab",
  " ": "Space",
  space: "Space",
  pageup: "Page Up",
  pagedown: "Page Down",
  home: "Home",
  end: "End",
  insert: "Ins",
  capslock: "Caps Lock",
}

/**
 * The keys of a combo as display labels, one per `Kbd`: `["⌘", "K"]` on a Mac and
 * `["Ctrl", "K"]` elsewhere. Pass `apple` to render one platform on the server.
 */
function hotkeyKeys(combo: string, apple = isApplePlatform()): string[] {
  const parsed = parseHotkey(combo.split(",")[0] ?? combo)
  const out: string[] = []
  if (apple) {
    // Apple order: Control, Option, Shift, Command.
    if (parsed.ctrl) out.push(SYMBOLS_APPLE.ctrl as string)
    if (parsed.alt) out.push(SYMBOLS_APPLE.alt as string)
    if (parsed.shift) out.push(SYMBOLS_APPLE.shift as string)
    if (parsed.mod || parsed.meta) out.push(SYMBOLS_APPLE.mod as string)
  } else {
    // Everywhere else: Ctrl, Win, Alt, Shift.
    if (parsed.ctrl || parsed.mod) out.push(NAMES_OTHER.ctrl as string)
    if (parsed.meta) out.push(NAMES_OTHER.meta as string)
    if (parsed.alt) out.push(NAMES_OTHER.alt as string)
    if (parsed.shift) out.push(NAMES_OTHER.shift as string)
  }
  const key = parsed.key
  out.push(
    KEY_LABELS[key] ??
      (key.length === 1 ? key.toUpperCase() : key[0]?.toUpperCase() + key.slice(1)),
  )
  return out
}

/**
 * Full-text search across chats: a field, optional role filters, and results with the matched
 * words marked in the title and in a snippet of the message that matched. A combobox: arrows move,
 * Enter opens, Cmd/Ctrl+Enter opens in a new tab.
 */
export function ChatSearch({
  chats,
  results: resultsProp,
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  loading = false,
  error,
  onRetry,
  onOpen,
  assistantName = "Assistant",
  roleFilter = true,
  role: roleProp,
  defaultRole = "all",
  onRoleChange,
  recentLimit = 6,
  now: nowProp,
  locale,
  debounceMs = 150,
  placeholder = "Search chats…",
  clearOnEscape = true,
  autoFocus = false,
  inputRef: inputRefProp,
  apple: appleProp,
  className,
  ...props
}: ChatSearchProps) {
  const detectedApple = useApplePlatform()
  const apple = appleProp ?? detectedApple
  const [queryState, setQueryState] = React.useState(defaultQuery)
  const query = queryProp ?? queryState
  const [roleState, setRoleState] = React.useState<ChatSearchRole>(defaultRole)
  const role = roleProp ?? roleState
  const server = resultsProp !== undefined
  const baseId = React.useId()
  const listboxId = `${baseId}-results`
  const localInput = React.useRef<HTMLInputElement>(null)
  // The clock is read after mount, never during render (Next.js prerender).
  const [mountTime, setMountTime] = React.useState<number | null>(null)
  React.useEffect(() => setMountTime(Date.now()), [])
  const nowTime =
    nowProp === undefined ? mountTime : typeof nowProp === "number" ? nowProp : nowProp.getTime()

  const setQuery = (next: string) => {
    if (queryProp === undefined) setQueryState(next)
    if (!server || debounceMs <= 0) onQueryChange?.(next)
  }
  const debounced = useChatcnShellDebounced(query, debounceMs)
  // Server mode: tell the caller once typing settles.
  const notified = React.useRef(query)
  React.useEffect(() => {
    if (!server || debounceMs <= 0 || notified.current === debounced) return
    notified.current = debounced
    onQueryChange?.(debounced)
  }, [server, debounced, debounceMs, onQueryChange])

  const setRole = (next: ChatSearchRole) => {
    if (roleProp === undefined) setRoleState(next)
    onRoleChange?.(next)
  }

  const searching = query.trim().length > 0
  const settledQuery = server ? query : debounced
  const results = React.useMemo(() => {
    if (server) return resultsProp ?? []
    if (!settledQuery.trim()) return recentChats(chats ?? [], recentLimit)
    return searchChats(chats ?? [], settledQuery, { role })
  }, [server, resultsProp, chats, settledQuery, role, recentLimit])
  const showingRecent = !server && !settledQuery.trim()
  const pending = loading || (!server && query !== debounced)
  const showSpinner = useDelayed(pending && searching)

  const [cursor, setCursor] = React.useState({ key: "", index: 0 })
  const listKey = `${settledQuery}|${role}`
  const active = results.length
    ? cursor.key === listKey
      ? Math.min(cursor.index, results.length - 1)
      : 0
    : -1
  const optionId = (i: number) => `${baseId}-result-${i}`

  const move = (index: number) => {
    setCursor({ key: listKey, index })
    document.getElementById(optionId(index))?.scrollIntoView({ block: "nearest" })
  }

  const open = (index: number, newTab: boolean) => {
    const result = results[index]
    if (result) onOpen?.(result, { newTab })
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return
    const count = results.length
    if (event.key === "ArrowDown" && count) {
      event.preventDefault()
      move((active + 1) % count)
    } else if (event.key === "ArrowUp" && count) {
      event.preventDefault()
      move((active - 1 + count) % count)
    } else if (event.key === "Enter" && active !== -1) {
      event.preventDefault()
      open(active, event.metaKey || event.ctrlKey)
    } else if (event.key === "Escape" && clearOnEscape && query) {
      event.preventDefault()
      event.stopPropagation()
      setQuery("")
    }
  }

  const setInputRef = (node: HTMLInputElement | null) => {
    localInput.current = node
    if (typeof inputRefProp === "function") inputRefProp(node)
    else if (inputRefProp) inputRefProp.current = node
  }

  React.useEffect(() => {
    if (autoFocus) localInput.current?.focus({ preventScroll: true })
  }, [autoFocus])

  const hasError = Boolean(error)
  const count = results.length
  const announcement =
    !searching || pending
      ? ""
      : hasError
        ? "Search failed"
        : count === 0
          ? "No chats match"
          : `${count} ${count === 1 ? "chat" : "chats"} found`

  return (
    <div
      data-slot="chat-search"
      data-search-state={
        hasError ? "error" : pending ? "searching" : searching ? "results" : "idle"
      }
      className={cn("flex min-h-0 flex-col", className)}
      {...props}
    >
      {/* Field */}
      <div className="flex h-12 shrink-0 items-center gap-3 px-4 pointer-coarse:h-14">
        <SearchIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4.5 shrink-0" />
        <input
          ref={setInputRef}
          role="combobox"
          aria-expanded={count > 0}
          aria-controls={listboxId}
          aria-autocomplete="list"
          aria-activedescendant={active !== -1 ? optionId(active) : undefined}
          aria-label="Search chats"
          autoComplete="off"
          spellCheck={false}
          enterKeyHint="search"
          data-slot="chat-search-input"
          value={query}
          placeholder={placeholder}
          onChange={(event) => setQuery(event.target.value)}
          onKeyDown={onKeyDown}
          className="text-[0.9375rem]/[1.5rem] tracking-[-0.006em] text-(color:--chatcn-fg) placeholder:text-(color:--chatcn-fg-subtle) pointer-coarse:text-[1rem]/[1.5rem] pointer-coarse:tracking-[-0.01em] h-full min-w-0 flex-1 bg-transparent outline-none"
        />
        {showSpinner ? (
          <Spinner label="Searching" className="text-(color:--chatcn-fg-subtle) size-4" />
        ) : null}
        {query ? (
          <Button
            variant="ghost"
            size="icon-xs"
            aria-label="Clear search"
            onClick={() => {
              setQuery("")
              localInput.current?.focus()
            }}
            className="-me-1 pointer-coarse:size-11"
          >
            <XIcon />
          </Button>
        ) : null}
      </div>

      {/* Filters */}
      {roleFilter && !server ? (
        <div className="flex shrink-0 items-center gap-1 px-3 pb-2.5">
          <div role="radiogroup" aria-label="Search in" className="flex items-center gap-1">
            {ROLE_FILTERS.map((f) => {
              const checked = role === f.value
              return (
                // biome-ignore lint/a11y/useSemanticElements: a pill radio, not a native input
                <button
                  key={f.value}
                  type="button"
                  role="radio"
                  aria-checked={checked}
                  tabIndex={checked ? 0 : -1}
                  onClick={() => setRole(f.value)}
                  onKeyDown={(event) => {
                    const i = ROLE_FILTERS.findIndex((x) => x.value === role)
                    const dir = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0
                    if (!dir) return
                    event.preventDefault()
                    const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
                    const next =
                      ROLE_FILTERS[
                        (i + (rtl ? -dir : dir) + ROLE_FILTERS.length) % ROLE_FILTERS.length
                      ]
                    if (!next) return
                    setRole(next.value)
                    const group = event.currentTarget.parentElement
                    group?.querySelector<HTMLElement>(`[data-role-filter="${next.value}"]`)?.focus()
                  }}
                  data-role-filter={f.value}
                  className={cn(
                    "chatcn-focus text-[0.8125rem]/[1.25rem] h-7 rounded-full px-3 whitespace-nowrap select-none",
                    "ease-(--chatcn-ease-standard) transition-[background-color,color] duration-150",
                    checked
                      ? "bg-(color:--chatcn-fill-active) text-(color:--chatcn-fg)"
                      : "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill) hover:text-(color:--chatcn-fg)",
                    "pointer-coarse:h-9",
                  )}
                >
                  {f.label(assistantName)}
                </button>
              )
            })}
          </div>
        </div>
      ) : null}

      {/* Results */}
      <div className="border-(color:--chatcn-border) chatcn-scroll min-h-0 flex-auto overflow-y-auto overscroll-contain border-t">
        {hasError ? (
          <div role="alert" className="flex flex-col items-center gap-3 px-6 py-12 text-center">
            <CircleAlertIcon aria-hidden="true" className="text-(color:--chatcn-red) size-5" />
            <div className="flex flex-col gap-1">
              <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg)">Search is unavailable right now</p>
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">
                {typeof error === "string" ? error : "Check your connection, then retry."}
              </p>
            </div>
            {onRetry ? (
              <Button variant="outline" size="sm" onClick={onRetry} className="pointer-coarse:h-11">
                Retry search
              </Button>
            ) : null}
          </div>
        ) : count === 0 && searching && !pending ? (
          <div className="flex flex-col items-center gap-1 px-6 py-12 text-center">
            <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) text-balance">
              No chats match “{query.trim()}”
            </p>
            {role !== "all" && !server ? (
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)">
                Only {role === "user" ? "your messages" : `${assistantName} replies`} are searched.{" "}
                <button
                  type="button"
                  onClick={() => setRole("all")}
                  className="chatcn-focus text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) decoration-(color:--chatcn-border-strong) underline underline-offset-2 hover:decoration-current"
                >
                  Search all messages
                </button>
              </p>
            ) : (
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">
                Check the spelling, or search for fewer words.
              </p>
            )}
          </div>
        ) : count === 0 && !searching ? (
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) px-6 py-12 text-center">
            {pending ? "Searching…" : "Your chats show up here."}
          </p>
        ) : (
          <div className="p-2">
            {showingRecent ? (
              <div className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex h-8 items-center px-2 font-medium">
                Recent
              </div>
            ) : null}
            <div
              id={listboxId}
              role="listbox"
              aria-label={showingRecent ? "Recent chats" : "Results"}
              className={cn("flex flex-col gap-px", pending && searching && "opacity-60")}
            >
              {results.map((result, i) => {
                const isActive = i === active
                const snippet =
                  typeof result.snippet === "string"
                    ? { text: result.snippet, ranges: [], before: false, after: false }
                    : result.snippet
                return (
                  // biome-ignore lint/a11y/useKeyWithClickEvents lint/a11y/useFocusableInteractive: focus stays on the combobox, which handles the keys (aria-activedescendant)
                  <div
                    key={result.id}
                    id={optionId(i)}
                    role="option"
                    aria-selected={isActive}
                    data-slot="chat-search-result"
                    data-active={isActive ? "" : undefined}
                    onPointerMove={() => {
                      if (!isActive) setCursor({ key: listKey, index: i })
                    }}
                    onPointerDown={(event) => event.preventDefault()}
                    onClick={(event) => open(i, event.metaKey || event.ctrlKey)}
                    onAuxClick={(event) => {
                      if (event.button === 1) open(i, true)
                    }}
                    className={cn(
                      "rounded-(--chatcn-radius-md) flex cursor-default gap-3 px-2.5 py-2.5 select-none",
                      "data-[active]:bg-(color:--chatcn-fill-hover)",
                    )}
                  >
                    <MessageSquareIcon
                      aria-hidden="true"
                      className={cn(
                        "text-(color:--chatcn-fg-subtle) mt-0.5 size-4 shrink-0",
                        isActive && "text-(color:--chatcn-fg)",
                      )}
                    />
                    <div className="flex min-w-0 flex-1 flex-col gap-1">
                      <div className="flex min-w-0 items-baseline gap-3">
                        <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) min-w-0 flex-1 truncate">
                          <Marked text={result.title} ranges={result.titleRanges} variant="title" />
                        </span>
                        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex shrink-0 items-center gap-2 tabular-nums">
                          {result.matchCount && result.matchCount > 1 ? (
                            <span>{result.matchCount} matches</span>
                          ) : null}
                          <span>
                            {formatChatDate(
                              result.updatedAt,
                              nowTime ?? toTime(result.updatedAt),
                              locale,
                            )}
                          </span>
                        </span>
                      </div>
                      {snippet?.text ? (
                        <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) line-clamp-2 text-pretty [overflow-wrap:anywhere]">
                          {result.role ? (
                            <span className="text-(color:--chatcn-fg-subtle)">
                              {result.role === "user" ? "You" : assistantName}:{" "}
                            </span>
                          ) : null}
                          {snippet.before ? "…" : null}
                          <Marked text={snippet.text} ranges={snippet.ranges} variant="snippet" />
                          {snippet.after ? "…" : null}
                        </p>
                      ) : null}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </div>

      {/* Hints */}
      <div className="border-(color:--chatcn-border) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex h-10 shrink-0 items-center gap-4 border-t px-4 pointer-coarse:hidden">
        <span className="flex items-center gap-1.5">
          <span aria-hidden="true" className="flex gap-0.5">
            <Kbd>↑</Kbd>
            <Kbd>↓</Kbd>
          </span>
          Navigate
        </span>
        <span className="flex items-center gap-1.5">
          <Kbd aria-hidden="true">↵</Kbd>
          Open
        </span>
        <span className="flex items-center gap-1.5">
          <span aria-hidden="true" className="flex gap-0.5">
            {hotkeyKeys("mod+enter", apple).map((k) => (
              <Kbd key={k}>{k}</Kbd>
            ))}
          </span>
          Open in new tab
        </span>
      </div>

      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </div>
  )
}

/** `ChatSearch` in a dialog near the top of the screen. Opening a result closes it. */
export function ChatSearchDialog({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  hotkey = null,
  title = "Search chats",
  container,
  onOpen,
  className,
  ...props
}: ChatSearchDialogProps) {
  const [openState, setOpenState] = React.useState(defaultOpen)
  const open = openProp ?? openState
  const inputRef = React.useRef<HTMLInputElement>(null)
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }
  const openRef = React.useRef(open)
  openRef.current = open
  useChatcnHotkeys(
    hotkey
      ? {
          [hotkey]: () => {
            lastModality = "keyboard"
            setOpen(!openRef.current)
          },
        }
      : {},
  )

  // Opened or closed from the keyboard (the hotkey, Enter on a trigger, Escape): no animation.
  React.useEffect(trackModality, [])
  const [instant, setInstant] = React.useState(true)
  const [prevOpen, setPrevOpen] = React.useState(open)
  if (prevOpen !== open) {
    setPrevOpen(open)
    setInstant(lastModality === "keyboard")
  }

  return (
    <Dialog open={open} onOpenChange={(next) => setOpen(next)}>
      <DialogContent
        size="lg"
        showClose={false}
        container={container}
        initialFocus={inputRef}
        className={cn(
          "top-[12dvh] max-h-[min(36rem,calc(100dvh-14dvh-1rem))] translate-y-0",
          instant && "transition-none",
          className,
        )}
        backdropClassName={instant ? "transition-none" : undefined}
      >
        <DialogTitle className="sr-only">{title}</DialogTitle>
        <ChatSearch
          {...props}
          inputRef={inputRef}
          clearOnEscape={false}
          className="min-h-0 flex-auto"
          onOpen={(result, options) => {
            onOpen?.(result, options)
            if (!options.newTab) setOpen(false)
          }}
        />
      </DialogContent>
    </Dialog>
  )
}

export default ChatSearch

